import React from "react";

const MessageBubble = ({ sender, text }) => {
  return (
    <div
      style={{
        textAlign: sender === "user" ? "right" : "left",
        margin: "6px 0"
      }}
    >
      <span
        style={{
          display: "inline-block",
          padding: "8px 12px",
          borderRadius: "12px",
          background: sender === "user" ? "#DCF8C6" : "#F1F0F0",
          maxWidth: "80%"
        }}
      >
        {text}
      </span>
    </div>
  );
};

export default MessageBubble;
